#include "ViewerRuntime.h"
#include "WebPFixtures.h"
namespace {
void MakeBackgroundFixture(const fs::path& file,UINT w,UINT h,int mode){
    ComPtr<IWICImagingFactory> factory;winrt::check_hresult(CoCreateInstance(CLSID_WICImagingFactory,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&factory)));ComPtr<IWICStream> stream;winrt::check_hresult(factory->CreateStream(&stream));winrt::check_hresult(stream->InitializeFromFilename(file.c_str(),GENERIC_WRITE));ComPtr<IWICBitmapEncoder> encoder;winrt::check_hresult(factory->CreateEncoder(file.extension()==L".jpg"?GUID_ContainerFormatJpeg:GUID_ContainerFormatPng,nullptr,&encoder));winrt::check_hresult(encoder->Initialize(stream.Get(),WICBitmapEncoderNoCache));ComPtr<IWICBitmapFrameEncode> frame;winrt::check_hresult(encoder->CreateNewFrame(&frame,nullptr));winrt::check_hresult(frame->Initialize(nullptr));winrt::check_hresult(frame->SetSize(w,h));bool jpeg=file.extension()==L".jpg";int channels=jpeg?3:4;auto format=jpeg?GUID_WICPixelFormat24bppBGR:GUID_WICPixelFormat32bppBGRA;winrt::check_hresult(frame->SetPixelFormat(&format));std::vector<BYTE> bytes(size_t(w)*h*channels);
    for(UINT y=0;y<h;++y)for(UINT x=0;x<w;++x){auto i=(size_t(y)*w+x)*channels;if(mode==0){bytes[i]=BYTE(40+100*x/w);bytes[i+1]=BYTE(50+100*y/h);bytes[i+2]=180;if(!jpeg)bytes[i+3]=255;}else if(mode==2){bytes[i+2]=255;if(!jpeg)bytes[i+3]=128;}}
    winrt::check_hresult(frame->WritePixels(h,w*channels,UINT(bytes.size()),bytes.data()));winrt::check_hresult(frame->Commit());winrt::check_hresult(encoder->Commit());
}
COLORREF RenderPixel(HWND h,int x,int y,bool native=false){RECT r{};GetClientRect(h,&r);HDC dc=CreateCompatibleDC(nullptr);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=std::max(1L,r.right);info.bmiHeader.biHeight=-std::max(1L,r.bottom);info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* bits=nullptr;auto bitmap=CreateDIBSection(nullptr,&info,DIB_RGB_COLORS,&bits,nullptr,0);auto old=SelectObject(dc,bitmap);FillRect(dc,&r,GetSysColorBrush(COLOR_HIGHLIGHT));if(native)SendMessageW(h,WM_PRINTCLIENT,reinterpret_cast<WPARAM>(dc),PRF_CLIENT|PRF_ERASEBKGND);else PaintBackdrop(h,dc,r);auto color=GetPixel(dc,x,y);SelectObject(dc,old);DeleteObject(bitmap);DeleteDC(dc);return color;}
bool Near(COLORREF a,COLORREF b,int tolerance=2){return a!=CLR_INVALID&&b!=CLR_INVALID&&std::abs(int(GetRValue(a))-int(GetRValue(b)))<=tolerance&&std::abs(int(GetGValue(a))-int(GetGValue(b)))<=tolerance&&std::abs(int(GetBValue(a))-int(GetBValue(b)))<=tolerance;}
}
void RunV060UiTests(const fs::path& root,std::ostream& report){
    auto check=[&](bool ok,const char* label){if(!ok)throw std::runtime_error(label);report<<"PASS: v060 "<<label<<std::endl;};auto pump=[](){MSG m{};while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}};auto wait=[&](auto ready){auto end=GetTickCount64()+20000;while(!ready()){pump();if(GetTickCount64()>end)throw std::runtime_error("v060 timeout");Sleep(10);}};
    KillTimer(app.window,RecordTimer);struct Restore{~Restore(){ClearBackdrop(false);app.darkTheme=false;app.layout=L"right";app.sideWidth=400;ApplyTheme();SetTimer(app.window,RecordTimer,500,nullptr);}} restore;
    ClearBackdrop(false);check(ParseViewerSettings("{\"version\":3}").backgroundPath.empty(),"legacy settings default to no background");ViewerSettings settings;settings.backgroundPath=L"C:\\背景\\写真😀.png";check(ParseViewerSettings(SerializeViewerSettings(settings)).backgroundPath==settings.backgroundPath,"Unicode background path roundtrips");
    auto menu=BuildOptionsMenu();check((GetMenuState(menu,20,MF_BYCOMMAND)&MF_GRAYED)!=0,"clear action disabled before a background is configured");DestroyMenu(menu);
    auto folder=root/L"v060-images";fs::create_directories(folder);auto file=root/L"v060-background.png";MakeBackgroundFixture(file,320,180,0);MakeBackgroundFixture(folder/L"transparent.png",64,64,1);MakeBackgroundFixture(folder/L"half.png",64,64,2);auto bad=root/L"v060-bad.png";{std::ofstream out(bad);out<<"broken";}
    auto jpg=root/L"v060-background.jpg",webp=root/L"v060-background.webp";MakeBackgroundFixture(jpg,32,18,0);{std::ofstream out(webp,std::ios::binary);out.write(reinterpret_cast<const char*>(LosslessWebP),sizeof(LosslessWebP));}check(ReadBackdrop(jpg.wstring()).width==32&&ReadBackdrop(webp.wstring()).width==320,"JPEG and WebP backgrounds decode without external codecs");
    RequestBackdrop(file.wstring());wait([&]{return !app.backgroundLoading;});check(HasBackdrop()&&app.backgroundPath==file.wstring(),"asynchronous image load applies a valid background");check(ParseViewerSettings([&]{std::ifstream in(app.settings);return std::string((std::istreambuf_iterator<char>(in)),{});}()).backgroundPath==file.wstring(),"successful selection persists its path");
    auto previous=app.backgroundPath;RequestBackdrop(bad.wstring());wait([&]{return !app.backgroundLoading;});check(HasBackdrop()&&app.backgroundPath==previous,"invalid image leaves the previous background active");Result stale;stale.job.applyGeneration=app.backgroundGeneration-1;stale.job.path=L"stale.png";stale.pixels={1,1,{0,255,0,255}};AcceptBackdrop(stale);check(app.backgroundPath==previous,"obsolete decode cannot overwrite newer settings");
    app.layout=L"right";app.sideWidth=400;app.categoryMode=0;app.appliedQuery.clear();TabCtrl_SetCurSel(app.metadataTabs,0);OpenFolder(folder.wstring());wait([&]{return !app.folderPending&&ThumbnailsReady();});
    auto select=[&](const wchar_t* name){auto it=std::find(app.files.begin(),app.files.end(),(folder/name).wstring());check(it!=app.files.end(),"transparent fixture is listed");ListView_SetItemState(app.list,-1,0,LVIS_SELECTED|LVIS_FOCUSED);int i=int(it-app.files.begin());ListView_SetItemState(app.list,i,LVIS_SELECTED|LVIS_FOCUSED,LVIS_SELECTED|LVIS_FOCUSED);FlushSelectionUpdate();wait([&]{return app.previewDedicated;});Layout();};
    select(L"transparent.png");
    for(bool dark:{false,true}){app.darkTheme=dark;ApplyTheme();Layout();wait([&]{return ThumbnailsReady();});
        for(auto placement:{L"right",L"left",L"bottom"}){app.layout=placement;ResetSideScroll();Layout();RECT view{};GetClientRect(app.preview,&view);int x=std::max(0L,view.right/2),y=std::max(0L,std::min(60L,view.bottom/2));auto expected=RenderPixel(app.preview,x,y);check(Near(RenderPixel(app.preview,x,y,true),expected),"fully transparent selected image reveals side backdrop");
            POINT origin{x,y};MapWindowPoints(app.preview,app.window,&origin,1);auto plain=RenderPixel(app.window,origin.x,origin.y);int bg[]{GetRValue(ThemeBackground()),GetGValue(ThemeBackground()),GetBValue(ThemeBackground())};auto tint=RGB((GetRValue(plain)*127+bg[0]*128+127)/255,(GetGValue(plain)*127+bg[1]*128+127)/255,(GetBValue(plain)*127+bg[2]*128+127)/255);check(Near(expected,tint),"only side descendants receive the fixed half-theme overlay");
        }
        app.layout=L"right";ResetSideScroll();Layout();
        for(int field:{0,6,9}){auto h=app.simpleValues[field];SetWindowTextW(h,L"alpha sample");ShowWindow(h,SW_SHOW);RECT r{};GetClientRect(h,&r);int x=std::max(0L,r.right-3),y=std::max(0L,r.bottom-3);auto actual=RenderPixel(h,x,y,true),expected=RenderPixel(h,x,y);report<<"INFO: v060 field="<<field<<" native="<<actual<<" backdrop="<<expected<<std::endl;check(Near(actual,expected),"native metadata field background matches mapped backdrop");}
        for(int id:{Bookmarks,Options,Help,SortMenu,ResetView}){auto button=AppControl(id);check(Near(RenderPixel(button,5,3,true),RenderPixel(button,5,3)),"main button face reveals its mapped background");}
        RECT r{};GetClientRect(app.list,&r);int x=r.right-20,y=r.bottom-20;auto actual=RenderPixel(app.list,x,y,true),expected=RenderPixel(app.list,x,y);report<<"INFO: v060 list native="<<actual<<" backdrop="<<expected<<std::endl;check(Near(actual,expected),"native list empty space shows the continuous backdrop");
        int index=ListView_GetNextItem(app.list,-1,LVNI_SELECTED);RECT icon{};ListView_GetItemRect(app.list,index,&icon,LVIR_ICON);int ix=(icon.left+icon.right)/2,iy=(icon.top+icon.bottom)/2;ListView_SetItemState(app.list,index,0,LVIS_SELECTED);auto iconActual=RenderPixel(app.list,ix,iy,true),iconExpected=RenderPixel(app.list,ix,iy);report<<"INFO: v060 icon native="<<iconActual<<" backdrop="<<iconExpected<<std::endl;check(Near(iconActual,iconExpected),"unselected transparent list thumbnail preserves the background underneath");ListView_SetItemState(app.list,index,LVIS_SELECTED,LVIS_SELECTED);
    }
    select(L"half.png");int halfIndex=app.selected;RECT halfIcon{};ListView_GetItemRect(app.list,halfIndex,&halfIcon,LVIR_ICON);int hx=(halfIcon.left+halfIcon.right)/2,hy=(halfIcon.top+halfIcon.bottom)/2;ListView_SetItemState(app.list,halfIndex,0,LVIS_SELECTED);auto halfBase=RenderPixel(app.list,hx,hy),halfActual=RenderPixel(app.list,hx,hy,true);auto halfExpected=RGB(128+GetRValue(halfBase)*127/255,GetGValue(halfBase)*127/255,GetBValue(halfBase)*127/255);report<<"INFO: v060 half thumbnail="<<halfActual<<" expected="<<halfExpected<<std::endl;check(Near(halfActual,halfExpected,3),"partial-alpha list thumbnail blends over untinted main background");ListView_SetItemState(app.list,halfIndex,LVIS_SELECTED,LVIS_SELECTED);
    RECT original{};GetWindowRect(app.window,&original);for(int width:{900,1200}){SetWindowPos(app.window,nullptr,0,0,width,760,SWP_NOMOVE|SWP_NOZORDER|SWP_NOACTIVATE);Layout();RECT client{};GetClientRect(app.window,&client);auto center=RenderPixel(app.window,client.right/2,client.bottom/2);check(Near(center,RGB(180,100,90),4),"cover scaling stays centered across window resizes");RECT list{};GetClientRect(app.list,&list);check(Near(RenderPixel(app.list,list.right-20,list.bottom-20,true),RenderPixel(app.list,list.right-20,list.bottom-20)),"resized native list stays aligned with the main background");}
    SetWindowPos(app.window,nullptr,0,0,original.right-original.left,original.bottom-original.top,SWP_NOMOVE|SWP_NOZORDER|SWP_NOACTIVATE);Layout();
    RECT r{};GetClientRect(app.preview,&r);int x=r.right/2,y=std::min(60L,r.bottom/2);auto base=RenderPixel(app.preview,x,y),actual=RenderPixel(app.preview,x,y,true);auto expected=RGB(128+GetRValue(base)*127/255,GetGValue(base)*127/255,GetBValue(base)*127/255);check(Near(actual,expected,3),"partial alpha blends foreground over tinted side background");
    // Background remains fixed in window coordinates when side content moves.
    PhotoSummary longSummary=app.summary;longSummary.values[9]=std::wstring(1600,L'名');ShowSummary(longSummary);Layout();SendMessageW(app.side,WM_VSCROLL,SB_LINEDOWN,0);check(app.sideScroll>0,"side content has scrolled while a background is active");auto field=app.simpleValues[9];RECT fieldRect{};GetClientRect(field,&fieldRect);check(Near(RenderPixel(field,std::max(0L,fieldRect.right-2),std::max(0L,fieldRect.bottom-2),true),RenderPixel(field,std::max(0L,fieldRect.right-2),std::max(0L,fieldRect.bottom-2))),"scrolled RichEdit background stays mapped to its new position");ResetSideScroll();Layout();
    RequestBackdrop(file.wstring());ClearBackdrop(false);pump();check(!HasBackdrop()&&!app.backgroundLoading&&app.backgroundPath.empty(),"clear cancels pending image application");ClearBackdrop();check(ParseViewerSettings([&]{std::ifstream in(app.settings);return std::string((std::istreambuf_iterator<char>(in)),{});}()).backgroundPath.empty(),"clear persists disabled state");
    for(int field:{0,6,9}){auto h=app.simpleValues[field];RECT view{};GetClientRect(h,&view);check(Near(RenderPixel(h,std::max(0L,view.right-2),std::max(0L,view.bottom-2),true),ThemeBackground()),"cleared metadata field restores the solid theme background");}
    app.layout=L"right";app.darkTheme=false;ResetViewer();ApplyTheme();Layout();
}
int BackdropTest(){auto root=app.settings.parent_path();std::ofstream report(root/L"v060-result.txt");try{RunV060UiTests(root,report);report<<"ALL PASSED\n";return 0;}catch(const std::exception& e){report<<"FAIL: "<<e.what()<<std::endl;return 1;}}
